219	/// Run the `squash-push` op: preflight, then squash (skipped when
220	/// the source is empty and undescribed) + bookmark-set + push.
221	///
222	/// - With an empty source and the bookmark already matching both
223	///   the squash target and the remote, reports "already sync'd"
224	///   and exits 0: nothing to do.
225	/// - With an empty source but the remote behind, skips the squash
226	///   and still pushes.
227	pub fn squash_push(
228	    ctx: &mut Context,
229	    params: &SquashPushParams,
230	) -> Result<(), Box<dyn std::error::Error>> {
231	    debug!("squash_push: entry params={params:?}");
232	    let repo_str = params.repo.to_string_lossy().to_string();
233	    let cwd = std::path::Path::new(".");
234	    let sq = &params.squash;
235	    let bookmark = &params.bookmark;
236	
237	    preflight(params)?;
238	
239	    // Report an at-rest publish mismatch before touching anything
240	    // (0.69.0-3): the bookmark should match its origin counterpart
241	    // between runs, so a mismatch means an earlier publish was
242	    // lost. Publishing is this command's job, so it proceeds: the
243	    // report is the point, not a refusal. Suppressed when run as
244	    // push's `squash-push-bot` stage (see `report_publish_state`).
245	    if params.report_publish_state {
246	        match crate::common::bookmark_publish_state(&params.repo, bookmark)? {
247	            crate::common::PublishState::InSync => {}
248	            crate::common::PublishState::NeverPushed => info!(
249	                "squash-push: '{bookmark}' has never been pushed to origin: this run will \
250	                 publish it"
251	            ),
252	            crate::common::PublishState::Mismatch { local, remote } => warn!(
253	                "squash-push: '{bookmark}' ({}) does not match '{bookmark}@origin' ({}): an \
254	                 earlier publish was likely lost; this run will publish it",
255	                &local[..local.len().min(12)],
256	                &remote[..remote.len().min(12)]
257	            ),
258	        }
259	    }
260	
261	    // Empty-source handling: nothing to squash. If the bookmark
262	    // already matches both the target and the remote, nothing to
263	    // push either: report and exit 0.
264	    if rev_is_empty_undescribed(&params.repo, &sq.source)? {
265	        let target_cid = jj::cid_of(&params.repo, &sq.target)?;
266	        let bookmark_cid = jj::cid_of(&params.repo, bookmark)?;
267	        // OK: unresolvable remote bookmark (never pushed) -> treated as not sync'd
268	        let remote_cid =
269	            jj::cid_of(&params.repo, &format!("{bookmark}@origin")).unwrap_or_default();
270	        if bookmark_cid == target_cid && bookmark_cid == remote_cid {
271	            info!("squash-push: repo '{repo_str}' is already sync'd with remote");
272	            return Ok(());
273	        }
274	        info!(
275	            "squash-push: {} is empty, skipping squash, still pushing",
276	            sq.source
277	        );
278	    } else {
279	        info!("squash-push: squashing {} -> {}...", sq.source, sq.target);
280	        run(
281	            "jj",
282	            &[
283	                "squash",
284	                "--ignore-immutable",
285	                "--use-destination-message",
286	                "--from",
287	                &sq.source,
288	                "--into",
289	                &sq.target,
290	                "-R",
291	                &repo_str,
292	            ],
293	            cwd,
294	        )?;
295	    }
296	
297	    info!(
298	        "squash-push: setting bookmark '{bookmark}' to {}...",
299	        sq.target
300	    );
301	    ctx.session(&params.repo)?
302	        .bookmark_set(bookmark, &sq.target)?;
303	
304	    info!("squash-push: pushing '{bookmark}' to origin...");
305	    ctx.session(&params.repo)?.git_push_bookmark(bookmark)?;
306	
307	    info!("squash-push: done");
308	    Ok(())
309	}
