61	/// Crate-standard boxed-error result, aliased locally for brevity.
62	type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;
63	
64	/// One repo opened for mutation: workspace, repo at head, settings,
65	/// and whether the workspace is colocated with git.
66	pub struct RepoSession {
67	    /// The loaded workspace (owns the working copy).
68	    pub workspace: Workspace,
69	    /// The repo, loaded at (or advanced past) the op-store head.
70	    pub repo: Arc<ReadonlyRepo>,
71	    /// Settings from the user's real jj config (see `stacked_config`).
72	    pub settings: UserSettings,
73	    /// True when `.git` and the working copy are shared with git, so
74	    /// mutations must import from and export to the git side.
75	    pub colocated: bool,
76	}
77	
78	/// Load the user's jj configuration the way the jj CLI does.
79	///
80	/// Layers, lowest to highest: jj-lib defaults, `/etc/jj` (unix),
81	/// `$JJ_CONFIG` (overrides system and user paths) or the user files
82	/// (`~/.jjconfig.toml`, `<config dir>/jj/config.toml` + `conf.d`),
83	/// the repo config (`.jj/repo/config.toml`), then `JJ_USER` /
84	/// `JJ_EMAIL` overrides. Deviation from the CLI: no command-line
85	/// layer and no `EnvBase` layer (debug / color / pager knobs that
86	/// only affect CLI presentation).
87	fn stacked_config(repo_config_path: Option<&Path>) -> Result<StackedConfig> {
88	    let mut config = StackedConfig::with_defaults();
89	    // Keys the engine reads whose defaults ship with the jj CLI's
90	    // config files rather than jj-lib's (values match jj 0.43).
91	    config.add_layer(ConfigLayer::parse(
92	        ConfigSource::Default,
93	        r#"
94	        [snapshot]
95	        auto-track = "all()"
96	        max-new-file-size = "1MiB"
97	        [git]
98	        auto-local-bookmark = false
99	        "#,
100	    )?);
101	    let jj_config = std::env::var("JJ_CONFIG").ok();
102	
103	    if jj_config.is_none() && cfg!(unix) {
104	        load_file_if_exists(&mut config, ConfigSource::System, "/etc/jj/config.toml")?;
105	        load_dir_if_exists(&mut config, ConfigSource::System, "/etc/jj/conf.d")?;
106	    }
107	
108	    if let Some(paths) = &jj_config {
109	        for path in std::env::split_paths(paths).filter(|p| !p.as_os_str().is_empty()) {
110	            if path.is_dir() {
111	                config.load_dir(ConfigSource::User, path)?;
112	            } else {
113	                config.load_file(ConfigSource::User, path)?;
114	            }
115	        }
116	    } else {
117	        let home = std::env::var_os("HOME").map(PathBuf::from);
118	        let config_dir = match std::env::var_os("XDG_CONFIG_HOME") {
119	            Some(x) if !x.is_empty() => Some(PathBuf::from(x)),
120	            _ => home.as_ref().map(|h| h.join(".config")),
121	        };
122	        if let Some(home) = &home {
123	            load_file_if_exists(&mut config, ConfigSource::User, home.join(".jjconfig.toml"))?;
124	        }
125	        if let Some(dir) = &config_dir {
126	            load_file_if_exists(&mut config, ConfigSource::User, dir.join("jj/config.toml"))?;
127	            load_dir_if_exists(&mut config, ConfigSource::User, dir.join("jj/conf.d"))?;
128	        }
129	    }
130	
131	    if let Some(repo_path) = repo_config_path {
132	        load_file_if_exists(
133	            &mut config,
134	            ConfigSource::Repo,
135	            repo_path.join("config.toml"),
136	        )?;
137	    }
138	
139	    let mut env = ConfigLayer::empty(ConfigSource::EnvOverrides);
140	    if let Ok(value) = std::env::var("JJ_USER") {
141	        env.set_value("user.name", value)?;
142	    }
143	    if let Ok(value) = std::env::var("JJ_EMAIL") {
144	        env.set_value("user.email", value)?;
145	    }
146	    if !env.is_empty() {
147	        config.add_layer(env);
148	    }
149	    Ok(config)
150	}
151	
152	/// Add one config file as a layer when it exists.
153	fn load_file_if_exists(
154	    config: &mut StackedConfig,
155	    source: ConfigSource,
156	    path: impl Into<PathBuf>,
157	) -> Result<()> {
158	    let path = path.into();
159	    if path.is_file() {
160	        config.load_file(source, path)?;
161	    }
162	    Ok(())
163	}
164	
165	/// Add one config directory as a layer set when it exists.
166	fn load_dir_if_exists(
167	    config: &mut StackedConfig,
168	    source: ConfigSource,
169	    path: impl Into<PathBuf>,
170	) -> Result<()> {
171	    let path = path.into();
172	    if path.is_dir() {
173	        config.load_dir(source, path)?;
174	    }
175	    Ok(())
176	}
177	
178	/// True when the workspace shares its working copy with a colocated
179	/// git repo (jj-cli's `is_colocated_git_workspace`, minus the
180	/// canonicalized `.git`-symlink fallback: vc-x1 lays repos out with
181	/// a real `.git` directory).
182	fn is_colocated(workspace: &Workspace, repo: &Arc<ReadonlyRepo>) -> bool {
183	    let Ok(backend) = git::get_git_backend(repo.store()) else {
184	        return false;
185	    };
186	    let Some(git_workdir) = backend.git_workdir() else {
187	        return false;
188	    };
189	    if git_workdir == workspace.workspace_root() {
190	        return true;
191	    }
192	    let Ok(dot_git) = workspace.workspace_root().join(".git").canonicalize() else {
193	        return false;
194	    };
195	    git_workdir.canonicalize().ok().as_deref() == dot_git.parent()
196	}
197	
198	impl RepoSession {
199	    /// Open `path` for mutation: user settings, workspace, repo at
200	    /// the op-store head, colocation flag.
201	    pub fn open(path: &Path) -> Result<Self> {
202	        // Two-phase settings: the repo config layer lives under
203	        // `.jj/repo`, whose location the loaded workspace knows.
204	        let settings = UserSettings::from_config(stacked_config(None)?)?;
205	        let store_factories = default_backend_factories();
206	        let working_copy_factories = default_working_copy_factories();
207	        let workspace =
208	            Workspace::load(&settings, path, &store_factories, &working_copy_factories)?;
209	        let settings = UserSettings::from_config(stacked_config(Some(workspace.repo_path()))?)?;
210	        let workspace =
211	            Workspace::load(&settings, path, &store_factories, &working_copy_factories)?;
212	        let repo = workspace.repo_loader().load_at_head().block_on()?;
213	        let colocated = is_colocated(&workspace, &repo);
214	        Ok(RepoSession {
215	            workspace,
216	            repo,
217	            settings,
218	            colocated,
219	        })
220	    }
221	
222	    /// Take the git import/export lock the CLI takes around its
223	    /// import/snapshot/export cycle. `None` when not colocated.
224	    fn lock_git(&self) -> Result<Option<FileLock>> {
225	        if !self.colocated {
226	            return Ok(None);
227	        }
228	        let path = self.workspace.repo_path().join("git_import_export.lock");
229	        Ok(Some(FileLock::lock(path)?))
230	    }
231	
232	    /// The CLI's `maybe_snapshot`: import git HEAD, snapshot the
233	    /// working copy, import git refs, each its own operation.
234	    pub fn snapshot(&mut self) -> Result<()> {
235	        let _lock = self.lock_git()?;
236	        // Reload at head (under the lock when colocated): sessions
237	        // outlive single verbs in a `Context`, and another process
238	        // or a spawned `jj` may have committed operations since the
239	        // open or the previous verb.
240	        self.repo = self.workspace.repo_loader().load_at_head().block_on()?;
241	        if self.colocated {
242	            self.import_git_head()?;
243	        }
244	        self.snapshot_working_copy()?;
245	        if self.colocated {
246	            self.import_git_refs()?;
247	        }
248	        Ok(())
249	    }
250	
251	    /// Import a moved git HEAD (someone ran plain git here): check
252	    /// out the new head and reset the working-copy state to it.
253	    fn import_git_head(&mut self) -> Result<()> {
254	        let mut tx = self.repo.start_transaction();
255	        git::import_head(tx.repo_mut()).block_on()?;
256	        if !tx.repo().has_changes() {
257	            return Ok(());
258	        }
259	        debug!("git HEAD moved; importing");
260	        let new_git_head = tx.repo().view().git_head().clone();
261	        if let Some(new_git_head_id) = new_git_head.as_normal() {
262	            let name = self.workspace.workspace_name().to_owned();
263	            let head_commit = tx.repo().store().get_commit(new_git_head_id)?;
264	            let wc_commit = tx.repo_mut().check_out(name, &head_commit).block_on()?;
265	            let mut locked_ws = self.workspace.start_working_copy_mutation().block_on()?;
266	            // The git command that moved HEAD updated the files too,
267	            // so reset the state without touching the working copy.
268	            locked_ws.locked_wc().reset(&wc_commit).block_on()?;
269	            tx.repo_mut().rebase_descendants().block_on()?;
270	            self.repo = tx.commit("import git head").block_on()?;
271	            locked_ws.finish(self.repo.op_id().clone()).block_on()?;
272	        } else {
273	            tx.repo_mut().rebase_descendants().block_on()?;
274	            self.repo = tx.commit("import git head").block_on()?;
275	        }
276	        Ok(())
277	    }
278	
279	    /// Snapshot the working copy into the wc commit if the tree
280	    /// changed (the CLI's `snapshot_working_copy`).
281	    ///
282	    /// Deviation: no immutable-wc-commit branch. vc-x1 never edits
283	    /// an immutable commit, and evaluating `immutable_heads()` needs
284	    /// the CLI's revset-alias machinery.
285	    fn snapshot_working_copy(&mut self) -> Result<()> {
286	        let name = self.workspace.workspace_name().to_owned();
287	        let repo = self.repo.clone();
288	
289	        let auto_track_pattern = self.settings.get_string("snapshot.auto-track")?;
290	        let mut diagnostics = FilesetDiagnostics::new();
291	        let root = self.workspace.workspace_root().to_path_buf();
292	        let path_converter = RepoPathUiConverter::Fs {
293	            cwd: root.clone(),
294	            base: root,
295	        };
296	        let fileset_aliases = jj_lib::fileset::FilesetAliasesMap::new();
297	        let fileset_ctx = FilesetParseContext {
298	            aliases_map: &fileset_aliases,
299	            path_converter: &path_converter,
300	        };
301	        let auto_track =
302	            fileset::parse(&mut diagnostics, &auto_track_pattern, &fileset_ctx)?.to_matcher();
303	        let HumanByteSize(mut max_new_file_size) = self
304	            .settings
305	            .get_value_with("snapshot.max-new-file-size", TryInto::try_into)?;
306	        if max_new_file_size == 0 {
307	            max_new_file_size = u64::MAX;
308	        }
309	        let options = SnapshotOptions {
310	            base_ignores: self.base_ignores()?,
311	            progress: None,
312	            start_tracking_matcher: auto_track.as_ref(),
313	            force_tracking_matcher: &NothingMatcher,
314	            max_new_file_size,
315	        };
316	
317	        let mut locked_ws = self.workspace.start_working_copy_mutation().block_on()?;
318	        let Some(wc_commit_id) = repo.view().get_wc_commit_id(&name).cloned() else {
319	            return Ok(()); // Workspace deleted from the repo view.
320	        };
321	        let mut wc_commit = repo.store().get_commit(&wc_commit_id)?;
322	        match WorkingCopyFreshness::check_stale(locked_ws.locked_wc(), &wc_commit, &repo)
323	            .block_on()?
324	        {
325	            WorkingCopyFreshness::Fresh => {}
326	            WorkingCopyFreshness::Updated(wc_operation) => {
327	                self.repo = repo.reload_at(&wc_operation).block_on()?;
328	                let Some(id) = self.repo.view().get_wc_commit_id(&name).cloned() else {
329	                    return Ok(());
330	                };
331	                wc_commit = self.repo.store().get_commit(&id)?;
332	            }
333	            stale => {
334	                return Err(format!(
335	                    "the working copy is stale ({stale:?}); run `jj workspace update-stale` \
336	                     in {}",
337	                    self.workspace.workspace_root().display()
338	                )
339	                .into());
340	            }
341	        }
342	
343	        let (new_tree, _stats) = locked_ws.locked_wc().snapshot(&options).block_on()?;
344	        if new_tree.tree_ids_and_labels() != wc_commit.tree().tree_ids_and_labels() {
345	            debug!("working-copy tree changed; committing snapshot operation");
346	            let mut tx = self.repo.start_transaction();
347	            tx.set_is_snapshot(true);
348	            let mut_repo = tx.repo_mut();
349	            let new_wc_commit = mut_repo
350	                .rewrite_commit(&wc_commit)
351	                .set_tree(new_tree.clone())
352	                .write()
353	                .block_on()?;
354	            mut_repo.set_wc_commit(name.clone(), new_wc_commit.id().clone())?;
355	            mut_repo.rebase_descendants().block_on()?;
356	            if self.colocated {
357	                retry_git_lock(|| {
358	                    git::update_intent_to_add(
359	                        mut_repo.base_repo().as_ref(),
360	                        &wc_commit.tree(),
361	                        &new_wc_commit.tree(),
362	                    )
363	                    .block_on()?;
364	                    git::export_refs(mut_repo)?;
365	                    Ok(())
366	                })?;
367	            }
368	            self.repo = tx.commit("snapshot working copy").block_on()?;
369	        }
370	        locked_ws.finish(self.repo.op_id().clone()).block_on()?;
371	        Ok(())
372	    }
