412	    /// The gitignore chain snapshots respect: the user's global
413	    /// excludes file, then the git dir's `info/exclude`.
414	    fn base_ignores(&self) -> Result<Arc<GitIgnoreFile>> {
415	        let mut ignores = GitIgnoreFile::empty();
416	        let Ok(backend) = git::get_git_backend(self.repo.store()) else {
417	            return Ok(ignores);
418	        };
419	        let git_repo = backend.git_repo();
420	        let excludes = {
421	            let config = git_repo.config_snapshot();
422	            match config.string("core.excludesFile") {
423	                Some(value) => str::from_utf8(&value)
424	                    .ok()
425	                    .map(jj_lib::file_util::expand_home_path)
426	                    .map(|p| self.workspace.workspace_root().join(p)),
427	                None => {
428	                    let config_dir = match std::env::var_os("XDG_CONFIG_HOME") {
429	                        Some(x) if !x.is_empty() => Some(PathBuf::from(x)),
430	                        _ => std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".config")),
431	                    };
432	                    config_dir.map(|d| d.join("git").join("ignore"))
433	                }
434	            }
435	        };
436	        if let Some(path) = excludes {
437	            ignores = ignores.chain_with_file(RepoPath::root(), path)?;
438	        }
439	        ignores = ignores.chain_with_file(
440	            RepoPath::root(),
441	            backend.git_repo_path().join("info/exclude"),
442	        )?;
443	        Ok(ignores)
444	    }
