495	    /// The working-copy commit of this workspace.
496	    pub fn wc_commit(&self) -> Result<Commit> {
497	        let name = self.workspace.workspace_name();
498	        let id = self
499	            .repo
500	            .view()
501	            .get_wc_commit_id(name)
502	            .ok_or_else(|| format!("workspace {name:?} has no working-copy commit"))?;
503	        Ok(self.repo.store().get_commit(id)?)
