506	    /// Resolve `rev` against this session's view to exactly one
507	    /// commit.
508	    fn one_commit(&self, rev: &str) -> Result<Commit> {
509	        let ids = crate::common::resolve_revset(&self.workspace, &self.repo, rev)?;
510	        match ids.as_slice() {
511	            [id] => Ok(self.repo.store().get_commit(id)?),
512	            other => Err(format!(
513	                "expected exactly one commit for {rev:?}, got {}",
514	                other.len()
515	            )
516	            .into()),
517	        }
