574	    /// Snapshot, then rebase the branch of `source` onto `dest`
575	    /// (`jj rebase -b <source> -d <dest>`): the roots of
576	    /// `dest..source` are rebased onto `dest`, and `finish_tx`'s
577	    /// `rebase_descendants` carries their descendants along, the
578	    /// working-copy pointer included. Conflicts are written, not
579	    /// refused: callers keep their post-rebase conflict checks.
580	    pub fn rebase_branch(&mut self, source: &str, dest: &str) -> Result<()> {
581	        self.snapshot()?;
582	        let dest_commit = self.one_commit(dest)?;
583	        let root_ids = crate::common::resolve_revset(
584	            &self.workspace,
585	            &self.repo,
586	            &format!("roots({dest}..{source})"),
587	        )?;
588	        if root_ids.is_empty() {
589	            debug!("rebase_branch: '{source}' is already on '{dest}', nothing to do");
590	            return Ok(());
591	        }
592	        let mut tx = self.start_tx();
593	        for id in &root_ids {
594	            let commit = tx.repo().store().get_commit(id)?;
595	            jj_lib::rewrite::rebase_commit(tx.repo_mut(), commit, vec![dest_commit.id().clone()])
596	                .block_on()?;
597	        }
598	        self.finish_tx(
599	            tx,
600	            &format!(
601	                "rebase {} commits onto {}",
602	                root_ids.len(),
603	                dest_commit.id().hex()
604	            ),
605	        )
606	    }
